// ePAReportFieldsNotCarried lists the fields that a declaration type does not carry.
var ePAReportFieldsNotCarried = map[string][]string{}

// SubmitEPAReports submits a epareport declaration.
func (c *Client) SubmitEPAReports(ctx context.Context, variant EPAReportVariant, declaration EPAReportDeclaration) ([]Submission, error) {
	fields, err := ePAReportFieldsOf(variant, declaration)
	if err != nil {
		return nil, err
	}

	return c.submit(ctx, DocumentCode(variant), ePAReportEnvelope(variant, fields))
}

// ePAReportFieldsOf turns a epareport declaration into the fields of the payload.
func ePAReportFieldsOf(variant EPAReportVariant, declaration EPAReportDeclaration) (map[string]any, error) {
	payload := ePAReportPayloadOf(declaration)

	fields, err := declarationFields(payload)
	if err != nil {
		return nil, err
	}
	dropFields(fields, ePAReportFieldsNotCarried[string(variant)])

	return fields, nil
}

