// HireNoticeVariant is a type of the hirenotice declaration.
type HireNoticeVariant string

// The declarations of the family.
const (
	// HireNotice is the E3 declaration.
	HireNotice HireNoticeVariant = "E3"
)

// hireNoticeEnvelopeKeys returns the root and the inner key of a declaration.
func hireNoticeEnvelopeKeys(variant HireNoticeVariant) (string, string) {
	switch variant {
	case HireNotice:
		return "AnaggeliesE3", "AnaggeliaE3"
	default:
		return "", ""
	}
}

// hireNoticeEnvelope wraps the fields of a declaration the way the API expects them.
func hireNoticeEnvelope(variant HireNoticeVariant, fields map[string]any) map[string]any {
	root, inner := hireNoticeEnvelopeKeys(variant)
	return map[string]any{
		root: map[string]any{
			inner: []any{fields},
		},
	}
}

// hireNoticeFieldsNotCarried lists the fields that a declaration type does not carry.
var hireNoticeFieldsNotCarried = map[string][]string{}

// SubmitHireNotices submits a hirenotice declaration.
func (c *Client) SubmitHireNotices(ctx context.Context, variant HireNoticeVariant, declaration HireNoticeDeclaration) ([]Submission, error) {
	fields, err := hireNoticeFieldsOf(variant, declaration)
	if err != nil {
		return nil, err
	}

	return c.submit(ctx, DocumentCode(variant), hireNoticeEnvelope(variant, fields))
}

// hireNoticeFieldsOf turns a hirenotice declaration into the fields of the payload.
func hireNoticeFieldsOf(variant HireNoticeVariant, declaration HireNoticeDeclaration) (map[string]any, error) {
	payload := hireNoticePayloadOf(declaration)

	fields, err := declarationFields(payload)
	if err != nil {
		return nil, err
	}
	dropFields(fields, hireNoticeFieldsNotCarried[string(variant)])

	return fields, nil
}
